import React, { useState } from 'react';
import { addCamera } from '../services/api';
import { useApp } from '../context/AppContext';

export default function AddCameraModal({ onClose }) {
  const { refreshCameras } = useApp();
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [success, setSuccess] = useState('');

  const [form, setForm] = useState({
    name:     '',
    source:   '',
    location: ''
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = async () => {
    if (!form.name.trim())   return setError('Camera name is required');
    if (!form.source.trim()) return setError('Camera source is required');

    setLoading(true);
    try {
      await addCamera({
        name:     form.name.trim(),
        source:   form.source.trim(),
        location: form.location.trim() || 'Unknown'
      });
      setSuccess('Camera added successfully!');
      await refreshCameras();
      setTimeout(() => onClose(), 1200);
    } catch (err) {
      const msg = err.response?.data?.detail || 'Failed to add camera';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  // Overlay
  const overlay = {
    position: 'fixed', inset: 0,
    background: 'rgba(0,0,0,.75)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    zIndex: 1000
  };

  const modal = {
    background: '#111827',
    border: '1px solid #1e2d47',
    borderRadius: 12,
    padding: 24,
    width: 420,
    maxWidth: '90vw'
  };

  const label = {
    fontSize: 11, fontWeight: 600,
    color: '#94a3b8', marginBottom: 5,
    display: 'block', textTransform: 'uppercase', letterSpacing: '.5px'
  };

  const input = {
    width: '100%', background: '#0a0e1a',
    border: '1px solid #1e2d47', borderRadius: 6,
    padding: '8px 12px', color: '#e2e8f0',
    fontSize: 12, outline: 'none',
    marginBottom: 14
  };

  const sourceOptions = [
    { label: 'Webcam (index 0)',  value: '0' },
    { label: 'Webcam (index 1)',  value: '1' },
    { label: 'Webcam (index 2)',  value: '2' },
    { label: 'Webcam (index 3)',  value: '3' },
    { label: 'RTSP Stream',       value: 'rtsp://' },
    { label: 'HTTP Stream',       value: 'http://' },
    { label: 'Custom...',         value: 'custom' },
  ];

  const [sourceType, setSourceType] = useState('0');
  const [customSrc,  setCustomSrc]  = useState('');

  const handleSourceType = (val) => {
    setSourceType(val);
    if (val !== 'custom') setForm({ ...form, source: val });
    else setForm({ ...form, source: '' });
  };

  return (
    <div style={overlay} onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div style={modal}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <div>
            <h2 style={{ fontSize: 16, fontWeight: 700, color: '#fff', margin: 0 }}>Add New Camera</h2>
            <p style={{ fontSize: 11, color: '#64748b', margin: '3px 0 0' }}>Connect a new camera to the system</p>
          </div>
          <button
            onClick={onClose}
            style={{ background: 'none', border: 'none', color: '#64748b', fontSize: 20, cursor: 'pointer', lineHeight: 1 }}
          >✕</button>
        </div>

        {/* Camera Name */}
        <label style={label}>Camera Name *</label>
        <input
          style={input}
          name="name"
          placeholder="e.g. Camera 05 - Entrance"
          value={form.name}
          onChange={handleChange}
        />

        {/* Source Type */}
        <label style={label}>Source Type *</label>
        <select
          style={{ ...input, cursor: 'pointer' }}
          value={sourceType}
          onChange={(e) => handleSourceType(e.target.value)}
        >
          {sourceOptions.map((opt, i) => (
            <option key={i} value={opt.value}>{opt.label}</option>
          ))}
        </select>

        {/* Custom source input */}
        {sourceType === 'custom' && (
          <>
            <label style={label}>Custom Source URL</label>
            <input
              style={input}
              placeholder="rtsp://192.168.1.1/stream or /dev/video0"
              value={customSrc}
              onChange={(e) => {
                setCustomSrc(e.target.value);
                setForm({ ...form, source: e.target.value });
              }}
            />
          </>
        )}

        {/* RTSP hint */}
        {(sourceType === 'rtsp://' || sourceType === 'http://') && (
          <>
            <label style={label}>Stream URL</label>
            <input
              style={input}
              placeholder={sourceType === 'rtsp://' ? 'rtsp://192.168.1.100:554/stream' : 'http://192.168.1.100:8080/video'}
              value={form.source === sourceType ? '' : form.source}
              onChange={(e) => setForm({ ...form, source: e.target.value })}
            />
          </>
        )}

        {/* Location */}
        <label style={label}>Location</label>
        <input
          style={input}
          name="location"
          placeholder="e.g. Main Entrance, Parking Lot"
          value={form.location}
          onChange={handleChange}
        />

        {/* Preview info */}
        <div style={{ background: '#0a0e1a', border: '1px solid #1e2d47', borderRadius: 6, padding: '10px 12px', marginBottom: 16 }}>
          <div style={{ fontSize: 10, color: '#64748b', marginBottom: 4 }}>Preview</div>
          <div style={{ fontSize: 11, color: '#e2e8f0' }}>
            <span style={{ color: '#64748b' }}>Name: </span>{form.name || '—'}<br />
            <span style={{ color: '#64748b' }}>Source: </span>{form.source || '—'}<br />
            <span style={{ color: '#64748b' }}>Location: </span>{form.location || 'Unknown'}
          </div>
        </div>

        {/* Error / Success */}
        {error && (
          <div style={{ background: '#450a0a', border: '1px solid #7f1d1d', borderRadius: 6, padding: '8px 12px', marginBottom: 12, fontSize: 11, color: '#f87171' }}>
            ⚠ {error}
          </div>
        )}
        {success && (
          <div style={{ background: '#0d2010', border: '1px solid #166534', borderRadius: 6, padding: '8px 12px', marginBottom: 12, fontSize: 11, color: '#4ade80' }}>
            ✓ {success}
          </div>
        )}

        {/* Buttons */}
        <div style={{ display: 'flex', gap: 8 }}>
          <button
            onClick={onClose}
            style={{
              flex: 1, background: '#151d2e', border: '1px solid #1e2d47',
              color: '#94a3b8', padding: '9px', borderRadius: 6,
              fontSize: 12, fontWeight: 600, cursor: 'pointer'
            }}
          >
            Cancel
          </button>
          <button
            onClick={handleSubmit}
            disabled={loading}
            style={{
              flex: 2, background: loading ? '#1e3a5f' : '#3b82f6',
              border: 'none', color: '#fff', padding: '9px',
              borderRadius: 6, fontSize: 12, fontWeight: 700,
              cursor: loading ? 'not-allowed' : 'pointer'
            }}
          >
            {loading ? 'Adding Camera...' : '+ Add Camera'}
          </button>
        </div>

      </div>
    </div>
  );
}
